import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();if(s.findMedianSortedArrays(new int[]{1,3},new int[]{2})!=2||s.findMedianSortedArrays(new int[]{1,2},new int[]{3,4})!=2.5||s.findMedianSortedArrays(new int[]{},new int[]{1})!=1)throw new AssertionError();Random r=new Random(42);for(int t=0;t<2000;t++){int n=r.nextInt(20),m=r.nextInt(20);if(n+m==0)continue;int[] a=new int[n],b=new int[m],both=new int[n+m];for(int i=0;i<n;i++)a[i]=r.nextInt(21)-10;for(int i=0;i<m;i++)b[i]=r.nextInt(21)-10;Arrays.sort(a);Arrays.sort(b);System.arraycopy(a,0,both,0,n);System.arraycopy(b,0,both,n,m);Arrays.sort(both);double w=(both[(n+m-1)/2]+both[(n+m)/2])/2.0;if(s.findMedianSortedArrays(a,b)!=w)throw new AssertionError();}System.out.println("Samples and original edge/reference checks passed");}}